    public function test_e2e_01_personal_todo_becomes_project_task_visible_in_board_and_calendar():void
    {
        $c=$this->manager();$t=$this->service()->create($c,'Personal work','todo');$key=$t['public_key'];$this->service()->mutate($c,$key,$t['version'],'complete','complete');$t=$this->service()->get($c,$key);$t=$this->service()->mutate($c,$key,$t['version'],'reopen','reopen');
        $r=$this->sales();$project=$this->projects()->create($c,'APP','Application',$r['id'],'project');$preview=$this->projects()->previewTaskMove($c,$key,$project['project_key'],'task',['pending'=>'new']);$t=$this->projects()->moveTask($c,$preview,'convert');self::assertSame($key,$t['public_key']);self::assertSame('APP-1',$t['display_key']);
        $p=$this->pipeline($r['id']);$instance=DB::table('tm_workflow_instances')->where('task_id',$t['id'])->where('slot_key','main')->first();$move=$this->instances()->previewMove($c,$instance->instance_key,$p['pipeline_key'],['new'=>'new']);$this->instances()->moveToPipeline($c,$move,'project-pipeline');$t=$this->service()->get($c,$key);$this->dates()->change($c,$key,$t['version'],null,null,'2026-10-22 09:00:00','UTC',false,'reject','due');
        $board=$this->board(new Surface('my.tasks',['tasks'],['tasks'=>$p['pipeline_key']]));self::assertNotNull($board->card($this->uiBoard(),'tasks:'.$key));$events=$this->calendar()->fetch(new \Karnoweb\Calendar\Data\EventQuery(\Karnoweb\Calendar\Data\DateRange::ofLocalDays('2026-10-22','2026-10-23','UTC')),$this->uiCalendar());self::assertCount(1,$events->events);self::assertSame($key,$events->events[0]->reference->eventId);self::assertSame(1,DB::table('tm_tasks')->count());
    }
    public function test_e2e_02_real_crm_campaign_closes_hundred_members_with_exact_75_15_10_outcomes():void
    {
        $c=$this->manager();[$lead,$deal,$stages]=$this->crm();$life=$this->app->make(\Karnoweb\Crm\Services\CampaignLifecycleService::class);$campaign=$life->create(['name'=>'100 opportunities','channel'=>'email','branch_id'=>1]);$campaign=$life->activate($campaign);
        $source=new class implements \Karnoweb\TaskManager\Contracts\GroupSourceProvider{
            public function authorize(\Karnoweb\TaskManager\Context\ExecutionContext $c,string $id,string $action):void{if($c->actor!=='1'||!\Karnoweb\Crm\Models\Campaign::query()->whereKey($id)->where('branch_id',$c->scope)->exists()){throw new \Karnoweb\TaskManager\Exceptions\DomainError('not_found');}}
            public function closure(\Karnoweb\TaskManager\Context\ExecutionContext $c,string $id):array{$this->authorize($c,$id,'close');$r=\Karnoweb\Crm\Models\Campaign::query()->findOrFail($id);if($r->status!=='completed'||!$r->completed_at){throw new \Karnoweb\TaskManager\Exceptions\DomainError('group_source_invalid');}return ['revision'=>$r->snapshot_version,'cutoff_at'=>new \DateTimeImmutable($r->completed_at->format(DATE_ATOM))];}
        };$this->app->instance(\Karnoweb\TaskManager\Group\GroupSourceRegistry::class,new \Karnoweb\TaskManager\Group\GroupSourceRegistry(['crm.campaign'=>$source]));$ledger=new \Karnoweb\TaskManager\Tests\Support\CommittedFixtureLedger(DB::connection());$this->app->instance(\Karnoweb\TaskManager\Contracts\CommitEvidenceProvider::class,$ledger);
        $d=['initial'=>'new','states'=>['new'=>[],'reservation'=>[],'won'=>['terminal'=>'success'],'failed'=>['terminal'=>'failure']],'transitions'=>['reserve'=>['from'=>'new','to'=>'reservation','milestones'=>['reservation_passed']],'win'=>['from'=>'new','to'=>'won'],'fail_new'=>['from'=>'new','to'=>'failed','reason_codes'=>['campaign_ended']],'fail_reservation'=>['from'=>'reservation','to'=>'failed','reason_codes'=>['campaign_ended']],'contract_return'=>['from'=>'reservation','to'=>'reservation']]];
        $r=$this->workflows()->publish($c,'campaign',0,'workflow',$d);$map=['new'=>['state'=>'new'],'reservation'=>['state'=>'reservation'],'won'=>['state'=>'won'],'failed'=>['state'=>'failed']];$p=$this->pipelines()->create($c,'Campaign',$r['id'],$map,'campaign-pipeline');$contract=$this->pipelines()->create($c,'Contracts',$r['id'],$map,'contracts');
        $this->app->make(\Karnoweb\TaskManager\SLA\StagePolicyService::class)->publishSla($c,$p['pipeline_key'],'new',1,'early-sla',['duration_seconds'=>60]);
        $groups=$this->app->make(\Karnoweb\TaskManager\Group\GroupService::class);$group=$groups->register($c,'crm.campaign',(string)$campaign->id,['protected_milestones'=>['reservation_passed'],'failure_transitions'=>['new'=>'fail_new','reservation'=>'fail_reservation'],'reason_code'=>'campaign_ended'],'group');$references=[];$instances=[];
        for($n=0;$n<100;$n++){
            if($n===12){$this->app->make(\Karnoweb\TaskManager\SLA\StagePolicyService::class)->publishSla($c,$p['pipeline_key'],'new',2,'later-sla',['duration_seconds'=>86400]);}
            $row=$n===0?$deal:$this->app->make(\Karnoweb\Crm\Services\DealService::class)->create(['lead_id'=>$lead->id,'pipeline_id'=>$deal->pipeline_id,'pipeline_stage_id'=>$stages[0]->id,'branch_id'=>1,'assigned_to'=>1]);$i=$this->instances()->start($c,'crm.deal',(string)$row->id,$r['id'],'start-'.$n,pipelineKey:$p['pipeline_key']);$references[]=['instance_key'=>$i['instance_key'],'version'=>1];$instances[]=$i;
        }$groups->enroll($c,$group['group_key'],1,$references,'enroll');
        for($n=75;$n<90;$n++){$i=$this->instances()->transition($c,$instances[$n]['instance_key'],1,'reserve-'.$n,'reserve');$intent=DB::table('tm_milestone_intents')->where('instance_id',$i['id'])->first();$ledger->acknowledge($intent->intent_key,$this->clock->now());$this->app->make(\Karnoweb\TaskManager\Group\MilestoneService::class)->verify($c,$intent->intent_key,2,'verify-'.$n);if($n<80){$this->app->make(\Karnoweb\TaskManager\Handoff\HandoffService::class)->delegate($c,$i['instance_key'],2,$contract['pipeline_key'],$r['id'],'contracts',['reason_code'=>'contract_review','target_team'=>'contracts','returns'=>['approved'=>['transition'=>'contract_return']]],'contract-'.$n);}}
        for($n=90;$n<100;$n++){$this->instances()->transition($c,$instances[$n]['instance_key'],1,'win-'.$n,'win');}$this->clock->advance('+60 seconds');self::assertSame(12,$this->app->make(\Karnoweb\TaskManager\SLA\SlaService::class)->run($c)['events']);\Illuminate\Support\Carbon::setTestNow($this->clock->now());$life->complete($campaign);
        $preview=$groups->previewClosure($c,$group['group_key']);self::assertSame(['failed'=>75,'continued'=>15,'already_terminal'=>10,'manual_review'=>0,'denied'=>0],$preview['counts']);$run=$groups->executeClosure($c,$preview,'close-campaign');$first=$groups->process($c,$run['run_key'],40);self::assertNotSame('complete',$first['state']);do{$result=$groups->process($c,$run['run_key'],25);}while($result['state']!=='complete');$report=$groups->report($c,$run['run_key']);self::assertSame(['already_terminal'=>10,'continued'=>15,'failed'=>75],$report['counts']);$events=DB::table('tm_outbox')->count();$groups->process($c,$run['run_key']);self::assertSame($events,DB::table('tm_outbox')->count());self::assertSame(5,DB::table('tm_handoffs')->where('status','active')->count());self::assertSame(100,\Karnoweb\Crm\Models\Deal::query()->count());
    }
    public static function contractOutcomes():array{return [['approve','review'],['reject','new'],['cancel','new']];}
    #[DataProvider('contractOutcomes')]
    public function test_e2e_03_real_crm_opportunity_contract_quorum_and_explicit_return(string $outcome,string $expected):void
    {
        [$lead,$deal]=$this->crm();$this->grantDeal($deal->id,['2','3','4']);$c=$this->manager();$d=$this->definition();$d['states']['lost']=['terminal'=>'failure'];$d['states']['cancelled']=['terminal'=>'cancelled'];$d['transitions']['accept']=['from'=>'new','to'=>'won'];$d['transitions']['reject']=['from'=>'new','to'=>'lost','reason_codes'=>['rejected']];$d['transitions']['cancel']=['from'=>'new','to'=>'cancelled','reason_codes'=>['cancelled']];$d['transitions']['rework']=['from'=>'new','to'=>'new'];$r=$this->workflows()->publish($c,'contract',0,'workflow',$d);$map=['inbox'=>['state'=>'new'],'review'=>['state'=>'review'],'won'=>['state'=>'won'],'lost'=>['state'=>'lost'],'cancelled'=>['state'=>'cancelled']];$p=$this->pipelines()->create($c,'Sales',$r['id'],$map,'sales');$dest=$this->pipelines()->create($c,'Contract',$r['id'],$map,'contract');$this->app->make(\Karnoweb\TaskManager\SLA\StagePolicyService::class)->publishSla($c,$p['pipeline_key'],'inbox',1,'sla',['duration_seconds'=>3600,'pause_reasons'=>['handoff'],'max_pause_seconds'=>86400]);
        $approvals=$this->app->make(\Karnoweb\TaskManager\Approval\ApprovalService::class);$approvals->configureStage($c,$dest['pipeline_key'],'inbox',1,'approval',['mode'=>'quorum','approvers'=>['2','3','4'],'quorum'=>2,'approved_transition'=>'accept','rejected_transition'=>'reject','reject_reasons'=>['rejected']]);
        $origin=$this->instances()->start($c,'crm.deal',(string)$deal->id,$r['id'],'sales-start',pipelineKey:$p['pipeline_key']);$handoffs=$this->app->make(\Karnoweb\TaskManager\Handoff\HandoffService::class);$h=$handoffs->delegate($c,$origin['instance_key'],1,$dest['pipeline_key'],$r['id'],'contract',['reason_code'=>'contract_review','target_team'=>'contracts','returns'=>['approved'=>['transition'=>'review'],'rejected'=>['transition'=>'rework'],'cancelled'=>['transition'=>'rework']]],'delegate');$key=DB::table('tm_workflow_instances')->where('id',$h['destination_id'])->value('instance_key');$step=$approvals->active($c,$key);self::assertSame('waiting',$this->instances()->get($c,$origin['instance_key'])['lifecycle']);$this->clock->advance('+60 seconds');
        if($outcome==='approve'){$first=$approvals->vote($this->manager('2'),$step['step_key'],1,1,'vote-2','approve');self::assertSame('pending',$first['state']);$last=$approvals->vote($this->manager('3'),$step['step_key'],2,1,'vote-3','approve');self::assertSame('executed',$last['execution_state']);}
        elseif($outcome==='reject'){$approvals->vote($this->manager('2'),$step['step_key'],1,1,'vote-reject','reject','rejected');}
        else{$approvals->cancel($c,$step['step_key'],1,1,'cancel-step','request_recalled');$this->instances()->transition($c,$key,2,'cancel-contract','cancel',['reason_code'=>'cancelled']);}
        $returned=$handoffs->settle($c,$h['handoff_key'],1,'return');self::assertSame('resolved',$returned['status']);$after=$this->instances()->get($c,$origin['instance_key']);self::assertSame($expected,$after['current_state_key']);self::assertSame('1',$after['owner_ref']);self::assertSame(60,$this->app->make(\Karnoweb\TaskManager\SLA\SlaService::class)->get($c,$h['paused_visit_id'])['paused_seconds']);self::assertSame($deal->pipeline_stage_id,$deal->fresh()->pipeline_stage_id);
    }
    public function test_e2e_04_ticket_spawn_uses_real_crm_service_rollback_and_safe_retry():void
    {
        [$ticket,$origin,$sales,$r,$router]=$this->ticketFlow();$routes=$this->app->make(\Karnoweb\TaskManager\Handoff\LocalRouteService::class);$router->failAfterCreate=true;$this->error('host_crm_failure',fn()=>$routes->spawn($this->manager(),'ticket.sales-v1',$origin['instance_key'],1,$sales['pipeline_key'],$r['id'],'main','refer','sales_opportunity_identified','spawn'));self::assertSame(1,\Karnoweb\Crm\Models\Deal::query()->count());self::assertNull($ticket->fresh()->referred_deal_id);
        $router->failAfterCreate=false;$result=$routes->spawn($this->manager(),'ticket.sales-v1',$origin['instance_key'],1,$sales['pipeline_key'],$r['id'],'main','refer','sales_opportunity_identified','spawn');$again=$routes->spawn($this->manager(),'ticket.sales-v1',$origin['instance_key'],1,$sales['pipeline_key'],$r['id'],'main','refer','sales_opportunity_identified','spawn');self::assertSame($result,$again);self::assertSame(2,\Karnoweb\Crm\Models\Deal::query()->count());self::assertSame('crm.deal',$this->instances()->get($this->manager(),$result['destination_key'])['subject_type']);self::assertSame('referred',$this->instances()->get($this->manager(),$origin['instance_key'])['current_state_key']);self::assertStringNotContainsString('PRIVATE SUPPORT MESSAGE',json_encode($this->cases()->timeline($this->manager(),$result['case_key'])));
    }
    public function test_e2e_05_same_real_ticket_moves_pipeline_and_department_with_new_permissions():void
    {
        [$ticket,$origin,$sales]=$this->ticketFlow();$this->error('not_found',fn()=>$this->instances()->get($this->manager('2'),$origin['instance_key']));$preview=$this->instances()->previewMove($this->manager(),$origin['instance_key'],$sales['pipeline_key'],['new'=>'new']);$result=$this->app->make(\Karnoweb\TaskManager\Handoff\LocalRouteService::class)->move($this->manager(),'ticket.sales-v1',$preview,'sales_opportunity_identified','move');self::assertSame($origin['instance_key'],$result['instance_key']);self::assertSame('sales',$ticket->fresh()->department);self::assertSame((string)$ticket->id,$this->instances()->get($this->manager('2'),$origin['instance_key'])['subject_id']);$visits=$this->instances()->visits($this->manager('2'),$origin['instance_key']);self::assertCount(2,$visits);self::assertNotNull($visits[0]['exited_at']);self::assertNull($visits[1]['exited_at']);
    }
    public function test_e2e_06_real_opportunity_parallel_slots_preserve_independent_truth_and_join_all():void
    {
        [$lead,$deal]=$this->crm();$c=$this->manager();$d=$this->definition();$d['transitions']['accept']=['from'=>'new','to'=>'won'];$r=$this->workflows()->publish($c,'parallel',0,'workflow',$d);$p=$this->pipeline($r['id']);$origin=$this->instances()->start($c,'crm.deal',(string)$deal->id,$r['id'],'start',pipelineKey:$p['pipeline_key']);$dest=$this->pipelines()->create($c,'Reviews',$r['id'],['inbox'=>['state'=>'new'],'review'=>['state'=>'review'],'won'=>['state'=>'won']],'review-pipeline');$targets=[];foreach(['legal_review','risk_review']as$slot){$targets[]=['pipeline_key'=>$dest['pipeline_key'],'revision_id'=>$r['id'],'slot'=>$slot];}$handoffs=$this->app->make(\Karnoweb\TaskManager\Handoff\HandoffService::class);$group=$handoffs->parallel($c,$origin['instance_key'],1,$targets,['reason_code'=>'reviews','target_team'=>'contracts','returns'=>['approved'=>['transition'=>'review']]],['mode'=>'all','outcomes'=>['approved'],'priority'=>['approved'],'remaining'=>'keep_active_detached'],'parallel');$keys=[];foreach($group['members']as$m){$keys[]=DB::table('tm_workflow_instances')->where('id',$m['destination_id'])->value('instance_key');}
        $this->instances()->transition($c,$keys[0],1,'legal','accept');self::assertSame('awaiting_join',$handoffs->settle($c,$group['members'][0]['handoff_key'],1,'legal-return')['status']);self::assertSame('new',$this->instances()->get($c,$keys[1])['current_state_key']);$this->error('version_conflict',fn()=>$this->instances()->transition($c,$keys[1],2,'stale-risk','accept'));$this->instances()->transition($c,$keys[1],1,'risk','accept');$handoffs->settle($c,$group['members'][1]['handoff_key'],1,'risk-return');self::assertSame('review',$this->instances()->get($c,$origin['instance_key'])['current_state_key']);self::assertSame('resolved',DB::table('tm_handoff_groups')->where('id',$group['group_id'])->value('status'));self::assertSame(1,DB::table('tm_outbox')->where('action','handoff_returned')->count());
    }
